ta.textarea_for_edit:
{* お店の名前、キャッチコピーの表示設定
    value に 1 を指定：表示する
    value に 2 を指定：表示しない
*}
{assign var="flag" value="2"}
{if $stores.isUseResponsiveTheme}
<script type="text/javascript" src="/SHOP/js/drawer_menu.js"></script>
{/if}
<div id="header-inner">
    <div id="logo">
         <h1>
            {if $hfdesign.h_logo != ''}
            <a href="/" title="{$hfdesign.shopName|escape}" ><img src="{$hfdesign.h_logo}" class="{if $hfdesign.h_logop}float_left{else}float_right{/if}" alt="{$hfdesign.altLogo|escape}" ></a>
            {/if}
        </h1>

        {* お店の名前、キャッチコピーの表示 *}
        {if $flag == 1}
        <div class="shoplogo">
            <h1 class="siteName">
            <a href="/" title="{$hfdesign.shopName|escape}" >
                {$hfdesign.shopName|escape}
            </a>
            </h1>
            <h2 class="sitecopy">
            <a href="/" title="{$hfdesign.shopCachcopy|escape}" >
                {$hfdesign.shopCachcopy|escape}
            </a>
            </h2>
        </div>
        {/if}
    </div>
    <div id="hNav">
        {if $hfdesign.h_search == 1}
            <div id="searchbox_wrap">
                <div id="searchbox">
                    <p><img src="/hpgen/HPB/theme/img/t_search.jpg" alt="search" /></p>
                    <form action="{$stores.storeDomain}/SHOP/list.php" method="get" name="searchform">
                        <input type="text" value="{block name="textSearch"}{/block}" name="Search" class="searchbox"/>
                        <input type="image" name="submit" class="searchSubmit" src="/hpgen/HPB/theme/img/submitSearch.gif" alt="検索" onclick="search_back();this.form.submit();return false;"/>
                    </form>
                </div>
            </div>
        {/if}

        {if $hfdesign.h_keywordlink == 1}
            {load_keywordLink}
            <ul id="keyword">
                {if $keywordLink.keyword}
                        {foreach from=$keywordLink.keyword key=index item=data}
                                {if $data.keyword != ''}
                                    <li><a href="{$stores.storeDomain}/SHOP/keyword/{$data.url}" title="{$data.keyword|escape}">{$data.keyword|escape}</a><li>
                                {/if}
                        {/foreach}
                {/if}
            </ul>
        {/if}

        <nav>
            <ul id="header-nav">
              {if $hfdesign.mypageLink}
                <li id="header-nav-mypage">
                  <a class="header-mypage" onClick="javascript:openPage('{$stores.cartUrl}/login.cgi','mypage'); return false;" href="/_ga/login.cgi" title="{$hfdesign.mypageLink|escape}">{$hfdesign.mypageLink|escape}</a>
                </li>
              {/if}
              {if $hfdesign.cartLink}
                <li id="header-nav-cart">
                    <a class="header-cart" onClick="javascript:goCart();return false;" href="/_ga/cart.php" title="{$hfdesign.cartLink|escape}" >{$hfdesign.cartLink|escape}</a>
                </li>
              {/if}
              {if $stores.isUseResponsiveTheme}
                <li id="header-nav-drawer"><span></span></li>
              {/if}
            </ul>
        </nav>
    </div>
</div>

{* サブ紹介文1の表示設定
    value に 1 を指定：表示する
    value に 2 を指定：表示しない
*}
{assign var="flag" value="1"}

{if $flag == 1}
    {if $itemMaster.description2}
<section id="itemDetail-wrap">
        {if $itemMaster.kagoDesc2 == 'Y'}
    <div id="itemDetail-cont">
    {$descparts}
    </div>
        {/if}

    <div class="description">
        <p>{$itemMaster.description2}</p>
    </div>
</section>

        {if $reviewData.conf.status == 'Y' && $itemMaster.comment2 == 'Y' && $reviewData.messageList}
{$revparts}
        {/if}
    {/if}
{/if}

{* サブ紹介文2の表示設定
    value に 1 を指定：表示する
    value に 2 を指定：表示しない
*}
{assign var="flag" value="1"}

{if $flag == 1}
    {if $itemMaster.description3}
<section id="itemDetail-wrap">
        {if $itemMaster.kagoDesc3 == 'Y'}
    <div id="itemDetail-cont">
    {$descparts}
    </div>
        {/if}

    <div class="description">
        <p>{$itemMaster.description3}</p>
    </div>
</section>

        {if $reviewData.conf.status == 'Y' && $itemMaster.comment3 == 'Y' && $reviewData.messageList}
{$revparts}
        {/if}
    {/if}
{/if}

